/**
 * @file
 * @brief Codebooks of the TETRA ACELP decoder, defined in src/tetra/tetra_acelp_codebooks.c.
 *
 * The definitions are numeric data from ETSI EN 300 395-2, generated by
 * tools/tetra/extract_acelp_tables.py; their terms are in
 * LICENSES/LicenseRef-ETSI-EN-300-395-2-data.txt.
 */

#ifndef MBELIB_NEO_INTERNAL_TETRA_ACELP_CODEBOOKS_H
#define MBELIB_NEO_INTERNAL_TETRA_ACELP_CODEBOOKS_H

#include <stdint.h>

/* LSP split VQ (Q15 cosine domain): q1..q3 (8 bits), q4..q6 and q7..q10 (9 bits each). */
extern const int16_t tetra_lsp_cb1[256][3];
extern const int16_t tetra_lsp_cb2[512][3];
extern const int16_t tetra_lsp_cb3[512][4];

/* Gain VQ (6 bits): quantized prediction errors of the pitch and code energies, Q8 log2. */
extern const int16_t tetra_gain_cb[64][2];

#endif /* MBELIB_NEO_INTERNAL_TETRA_ACELP_CODEBOOKS_H */
